import { useEffect, useState } from "react";
import { getTutorProfile } from "../api";
import { getUserId } from "../auth";
import toast from "react-hot-toast";

export default function TutorDashboard() {
  const [tutor, setTutor] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const id = getUserId();
        const res = await getTutorProfile(id);
        setTutor(res);
      } catch (err) {
        toast.error("Failed to load tutor profile");
      }
    };
    fetchData();
  }, []);

  if (!tutor) return <div className="p-4">Loading...</div>;

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <h1 className="text-3xl font-bold mb-4">Welcome, {tutor.name}</h1>
      <p className="mb-2"><strong>Experience:</strong> {tutor.experience}</p>
      <p className="mb-2"><strong>Status:</strong> {tutor.is_certified ? "CERTIFIED" : "NOT CERTIFIED"}</p>
      <p className="mb-2"><strong>Expertise:</strong> {tutor.expertise_courses.join(", ")}</p>
      <p className="mb-2"><strong>Address:</strong> {tutor.address}</p>
      <p className="mb-4"><strong>Contact:</strong> {tutor.contact_info}</p>

      <h2 className="text-xl font-semibold mt-4">Matched Students</h2>
      {tutor.matched_students.length === 0 ? (
        <p className="text-yellow-500 mt-2">No students matched yet.</p>
      ) : (
        <ul className="list-disc ml-6 mt-2">
          {tutor.matched_students.map((s) => (
            <li key={s.id}>{s.name} — {s.address}</li>
          ))}
        </ul>
      )}
    </div>
  );
}
